#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
int main(){int n,m;cin>>n>>m;vector<string>a(n);for(auto&s:a)cin>>s;int N=n*m;vector<int>indeg(N),len(N),seen(N);string cyc="DIMA";auto neighbors=[&](int u,auto visit){int r=u/m,c=u%m;char next=cyc[(cyc.find(a[r][c])+1)%4];for(auto[dr,dc]:vector<pair<int,int>>{{1,0},{-1,0},{0,1},{0,-1}}){int x=r+dr,y=c+dc;if(x>=0&&x<n&&y>=0&&y<m&&a[x][y]==next)visit(x*m+y);}};queue<int>q;for(int u=0;u<N;u++)if(a[u/m][u%m]=='D'){seen[u]=1;q.push(u);}while(!q.empty()){int u=q.front();q.pop();neighbors(u,[&](int v){if(!seen[v]){seen[v]=1;q.push(v);}});}for(int u=0;u<N;u++)if(seen[u])neighbors(u,[&](int v){indeg[v]++;});int total=accumulate(seen.begin(),seen.end(),0),processed=0,best=0;for(int u=0;u<N;u++)if(seen[u]&&!indeg[u]){q.push(u);len[u]=1;}while(!q.empty()){int u=q.front();q.pop();processed++;best=max(best,len[u]);neighbors(u,[&](int v){len[v]=max(len[v],len[u]+1);if(--indeg[v]==0)q.push(v);});}if(processed<total)cout<<"Poor Inna!\n";else if(best<4)cout<<"Poor Dima!\n";else cout<<best/4<<'\n';}
